  // Line 1: 10 * €10.00 = €100.00, 10% discount = €10.00, bulk 2.5% of €90.00 = €2.25, after €87.75, VAT 21% = €18.43
  // Line 2: 5 * €20.00 = €100.00, 20% discount = €20.00, after €80.00, VAT 21% = €16.80
  // Total VAT: €18.43 + €16.80 = €35.23, Total discount: €32.25
  // Total: €200.00 - €32.25 + €35.23 = €202.98
  assert.match(text, /Total: €202\.98$/);
});

